"""Render saved world-only probes without altering or grading their text."""
import html
import json
import re
import sys
import tempfile
from pathlib import Path

source = Path(sys.argv[1] if len(sys.argv) > 1 else '.artifacts/world-directions-v9/worlds.json').resolve()
data = json.loads(source.read_text())
output = Path(sys.argv[2]) if len(sys.argv) > 2 else Path(tempfile.mkstemp(prefix='draftgpt-world-directions-', suffix='.html', dir='/tmp')[1])
e = lambda value: html.escape(str(value), quote=True)
label = lambda key: re.sub(r'([a-z])([A-Z])', r'\1 \2', key).capitalize()

def fields(value):
    if isinstance(value, dict):
        return '<dl>'+''.join(f'<dt>{e(label(k))}</dt><dd>{fields(v)}</dd>' for k,v in value.items())+'</dl>'
    if isinstance(value, list):
        return '<ul>'+''.join('<li>'+fields(v)+'</li>' for v in value)+'</ul>' if value else '<p>None.</p>'
    return '<p>'+e(value)+'</p>'

def world(item):
    b=item['blueprint']; w=b['world']; ident=item['id']
    return f'''<article id="{e(ident)}" class="world"><div class="summary"><span class="eyebrow">{e(ident.replace('-', ' '))}</span><h2>{e(w['name'])}</h2><p class="premise">{e(w['premise'])}</p><h3>The place and its magic</h3><p>{e(w['description'])}</p><h3>The conflict</h3><p>{e(w['conflict'])}</p><p class="muted"><b>Tone:</b> {e(w['tone'])}</p></div>
    <details><summary>Design direction — categories, not supplied lore</summary>{fields(item['direction'])}</details>
    <details><summary>Five color identities and visual guide</summary>{fields({'colors':b['colors'],'creative':b['creative']})}</details>
    <details><summary>All ten archetypes, mechanics and play plan</summary>{fields({'archetypes':b['archetypes'],'mechanics':b['mechanics'],'experience':b['experience'],'influences':b['influences']})}</details>
    <label for="notes-{e(ident)}">Your notes: premise variety, literal prose, internal variety</label><textarea id="notes-{e(ident)}" data-notes="{e(ident)}" rows="3"></textarea></article>'''

observations_path=source.with_name('observations.json')
observations=json.loads(observations_path.read_text()) if observations_path.exists() else []
options=''.join(f'<option value="{e(w["id"])}">{e(w["blueprint"]["world"]["name"])}</option>' for w in data['worlds'])
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>DraftGPT — Five new world directions</title><style>
:root{--bg:#f2efe7;--paper:#fffdf8;--ink:#243539;--muted:#596762;--line:#cdd5cc;--accent:#256859}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.65 system-ui,sans-serif}header{background:var(--ink);color:var(--paper);padding:40px max(24px,calc((100vw - 1160px)/2))}header p{max-width:850px;color:#e0e7df}h1{font-size:clamp(34px,5vw,60px);line-height:1.12;letter-spacing:-.04em;margin:12px 0 25px}h2{font-size:29px;line-height:1.2;margin:8px 0 20px}h3{font-size:17px;margin:23px 0 10px}p{margin:0 0 17px}main,nav,footer{max-width:1208px;margin:auto;padding:24px}nav{display:flex;gap:22px;flex-wrap:wrap}a{color:var(--accent);text-underline-offset:4px}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.1em;font-weight:700}.facts{display:flex;gap:30px;flex-wrap:wrap;margin-top:26px}.facts strong{font-size:27px;display:block}.facts span{font-size:13px}.intro{max-width:900px;margin-bottom:30px}.world{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:28px;margin:25px 0;scroll-margin-top:20px;min-width:0}.world p{overflow-wrap:anywhere}.premise{font:21px/1.55 Georgia,serif;border-left:3px solid var(--accent);padding-left:18px}.muted{color:var(--muted);font-size:14px}details{border-top:1px solid var(--line);padding:14px 0}summary{font-weight:650;cursor:pointer}details[open]>summary{margin-bottom:18px}dl{margin:16px 0}dt{font-weight:700;font-size:13px;color:var(--accent)}dd{margin:0 0 14px}dd p{margin:3px 0}ul{padding-left:22px}li{padding:8px 0}label{display:block;font-size:14px;font-weight:650;margin-top:20px}textarea,select,button{font:inherit;background:var(--paper);color:var(--ink);border:1px solid #879d92;border-radius:6px;padding:10px}textarea{width:100%;resize:vertical;margin-top:7px}select{width:100%;margin-top:8px}button{cursor:pointer;margin:10px 0}a:focus-visible,summary:focus-visible,select:focus-visible,textarea:focus-visible,button:focus-visible{outline:3px solid #b16b24;outline-offset:4px}.compare{display:none}.js .compare{display:block}.controls,.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}.pair .world{margin-top:20px}.note{padding:18px;border-left:3px solid #9e7027;background:#eee5cf}.method{background:var(--paper);border:1px solid var(--line);padding:25px;border-radius:12px}footer{font-size:13px;color:var(--muted)}@media(max-width:700px){.controls,.pair{grid-template-columns:1fr}.world{padding:20px}main,nav,footer{padding:16px}}@media print{body{background:white}header{background:white;color:var(--ink);padding:0}header p{color:var(--ink)}nav,button,textarea,label,.controls{display:none}.compare{display:none!important}.world{border:0;padding:0;break-inside:avoid}.world details{display:block}h1{font-size:32pt}}
</style></head><body><header><span class="eyebrow">DraftGPT · prompt 9 · world-only probe</span><h1>Broader premises.<br>Literal descriptions.</h1><p>Five fresh worlds built from different design questions. No supplied fantasy scenes, no professional personas, no story examples in the prompt.</p><div class="facts"><div><strong>5</strong><span>full world and archetype briefs</span></div><div><strong>0</strong><span>cards or images generated</span></div><div><strong>__REQUESTS__</strong><span>requests, including structural retries</span></div><div><strong>$__COST__</strong><span>estimated text cost</span></div></div></header>
<nav><a href="#compare">Compare two worlds</a><a href="#worlds">Read all five</a><a href="#method">What changed</a><button id="export">Download notes</button></nav><main>
<div class="intro"><p>The previous worlds repeated terrain, materials and name stems. This revision varies the setting’s focus, conflict, access to magic and visual emphasis. Category choices favor those used least often in recent runs. The actual lore is invented by Luna.</p><p class="note">Read for three things: Are the central magical mechanisms different? Does each description make literal sense? Do the colors and archetypes give each world internal variety? These are unedited model outputs, not approved settings or a claim that repetition is solved.</p></div>
<section id="compare" class="compare"><h2>Read two premises together.</h2><div class="controls"><label for="left">Left world<select id="left">__OPTIONS__</select></label><label for="right">Right world<select id="right">__OPTIONS__</select></label></div><div class="pair" id="pair"></div></section>
<section class="method"><h2>Inspection notes, not a pass verdict.</h2>__OBSERVATIONS__</section><section id="worlds"><h2>All five worlds.</h2><p class="muted">Expand the color identities and archetypes to inspect repetition within a world. Notes remain in this browser when storage is available; export them to keep a copy.</p><p id="status" role="status"></p>__WORLDS__</section>
<section id="method" class="method"><h2>What changed—and what this does not prove.</h2><ul><li>Removed repeated fantasy-scene examples and the requirement to begin with extraordinary terrain.</li><li>Removed persona prompts and the pool of prewritten magical scenarios.</li><li>Rotated broad structural categories using the application’s recent-use allocation policy; the probe starts with empty history. No other world’s names, ideas or lore enter a request.</li><li>Required literal premise, description and conflict, with a short complete premise sentence. Card flavor may still use precise concrete-to-concrete comparisons.</li><li>Asked for different subject families, magical actions and gameplay loops within a world.</li><li>Kept the same Luna model, low reasoning, empty player input, five colors, ten archetypes and Modern Horizons target.</li></ul><p>__LIMITATIONS__</p><p>Different category assignments cannot guarantee different output. The prior prompt-8 results are historical references, not concurrent controls. All successful outputs and structural retries are retained; none were rerolled for taste. Costs use the repository’s usage estimates, not invoice reconciliation.</p><p><a href="__JSON__">Full world JSON</a> · <a href="__CONFIG__">Frozen inputs and source hashes</a> · <a href="__CALLS__">Exact requests and results</a></p></section>
</main><footer>Prompt revision informed by <a href="https://developers.openai.com/api/docs/guides/prompt-engineering">OpenAI’s guidance on instructions, examples and evaluation</a>. The specific anchoring diagnosis is an inference from this project’s prompts and outputs. This document works offline; no art assets or external scripts are required.</footer>
<script>
'use strict';document.documentElement.classList.add('js');
const left=document.getElementById('left'),right=document.getElementById('right');
function render(){const pair=document.getElementById('pair');pair.replaceChildren();for(const select of [left,right]){const article=document.createElement('article');article.className='world';article.append(document.querySelector('#'+select.value+' .summary').cloneNode(true));const link=document.createElement('a');link.href='#'+select.value;link.textContent='Read the complete guide and add notes';article.append(link);pair.append(article);}}
right.selectedIndex=1;left.addEventListener('change',render);right.addEventListener('change',render);render();
const key='draftgpt-world-directions-v9-notes',status=document.getElementById('status');let notes={};try{notes=JSON.parse(localStorage.getItem(key)||'{}');if(!notes||typeof notes!=='object'||Array.isArray(notes))notes={};}catch{status.textContent='Storage unavailable; export your notes before closing.';}
document.querySelectorAll('textarea[data-notes]').forEach(t=>{t.value=typeof notes[t.dataset.notes]==='string'?notes[t.dataset.notes]:'';t.addEventListener('input',()=>{notes[t.dataset.notes]=t.value;try{localStorage.setItem(key,JSON.stringify(notes));status.textContent='Notes saved in this browser.';}catch{status.textContent='Export notes before closing this tab.';}});});
document.getElementById('export').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({study:'world-directions-v9',savedAt:new Date().toISOString(),notes},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='draftgpt-world-direction-notes.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
</script></body></html>'''
for key,value in {'OBSERVATIONS':''.join('<p>'+e(x)+'</p>' for x in observations) or '<p>No manual inspection notes recorded.</p>','REQUESTS':data['requestCount'],'COST':f'{data["estimatedCost"]:.5f}','OPTIONS':options,'WORLDS':''.join(world(w) for w in data['worlds']),'LIMITATIONS':e(data['config']['limitations']),'JSON':source.as_uri(),'CONFIG':source.with_name('config.json').as_uri(),'CALLS':source.with_name('calls').as_uri()}.items():
    page=page.replace('__'+key+'__',str(value))
output.write_text(page,encoding='utf-8')
print(output)
